import { splitFrames } from './split-frames.mjs';

function properPrefixSuffixLength(text, delimiter) {
  let longest = 0;
  for (let n = 1; n < delimiter.length; n++) {
    if (text.endsWith(delimiter.slice(0, n))) {
      longest = n;
    }
  }
  return longest;
}

function assertPendingWithinLimit(pending, delimiter, maxBuffer) {
  const countable = pending.length - properPrefixSuffixLength(pending, delimiter);
  if (countable > maxBuffer) {
    throw new RangeError();
  }
}

export function createFramer({ delimiter = '\r\n', maxBuffer = 1024 } = {}) {
  if (typeof delimiter !== 'string' || delimiter.length === 0) {
    throw new TypeError();
  }
  if (!Number.isInteger(maxBuffer) || maxBuffer < 0) {
    throw new RangeError();
  }

  let pending = '';
  let closed = false;

  return {
    push(chunk) {
      if (closed) {
        throw new Error('closed');
      }
      if (typeof chunk !== 'string') {
        throw new TypeError();
      }
      pending += chunk;
      const { frames, rest } = splitFrames(pending, delimiter);
      for (const frame of frames) {
        if (frame.length > maxBuffer) {
          throw new RangeError();
        }
      }
      pending = rest;
      assertPendingWithinLimit(pending, delimiter, maxBuffer);
      return frames;
    },
    finish() {
      if (closed) {
        throw new Error('closed');
      }
      closed = true;
      if (pending.length === 0) {
        return [];
      }
      if (pending.length > maxBuffer) {
        throw new RangeError();
      }
      const tail = pending;
      pending = '';
      return [tail];
    },
  };
}

