export function splitFrames(text, delimiter) {
  if (typeof text !== 'string') {
    throw new TypeError();
  }
  if (typeof delimiter !== 'string' || delimiter.length === 0) {
    throw new TypeError();
  }
  const frames = [];
  let start = 0;
  for (;;) {
    const at = text.indexOf(delimiter, start);
    if (at === -1) {
      return { frames, rest: text.slice(start) };
    }
    frames.push(text.slice(start, at));
    start = at + delimiter.length;
  }
}

